test('drafting worker discards refused replacements, frees failed rounds and checks fold and body sources', async () => {
  const sent=[], freed=[], calls=[]; let failure, flatOnly=false;
  const values={default:async()=>{},program_info:()=> '{}',calibration_dictionaries:()=> '["DICT_4X4_50"]',
    run:()=> {
      if(failure==='run') throw Error('run refused');
      return {page:()=>{if(failure==='page') throw Error('page refused');return '{"status":"CONVERGED","zip":"round.zip"}';},
        zip:()=>{if(failure==='zip') throw Error('zip refused');return new Uint8Array([1]);},
        file:n=>{if(failure===n) throw Error('file refused');return new TextEncoder().encode(n==='pattern.json'?(flatOnly?'{"pieces":[]}':'{"pieces":[{"placement":{"part":"torso"}}]}'):'{}');},
        free:()=>freed.push('round')};
    },
    WebBody:class {constructor(bytes){if(bytes[0]===0)throw Error('body refused');}free(){freed.push('body');}},
    inspect_body:(_body,measurements,source)=>{calls.push({inspect:measurements,source});
      if(source==='refused')throw Error('import refused');return '{"cloth_simulated":false,"raw":-0.0}';},
    fold_up:()=>{calls.push('fold');return {report:()=>'{"gating":[]}',viewer:()=>'<html/>',free:()=>freed.push('fold')};},
    fold_up_with_body_fit:(_body,_pattern,_measurements,_fit,mm,twoStart,source,angle)=>{
      calls.push({source,mm,twoStart,angle});if(source==='refused')throw Error('import refused');
      return {report:()=>'{"body":{"provenance":"MODEL_FIT"}}',viewer:()=>'<html/>',free:()=>freed.push('import')};},
    fold_up_configured:(_body,_pattern,_measurements,_fit,settings,source)=>{
      calls.push({settings:JSON.parse(settings),source});if(source==='refused')throw Error('configured source refused');
      return {report:()=>'{"numerical":{"settling":{"steps":2}},"raw":-0.0}',viewer:()=>'<html/>',free:()=>freed.push('configured')};}};
  const context=vm.createContext({JSON,Date,TextDecoder,Uint8Array,WebAssembly,Error,self:{},onmessage:null,postMessage:m=>sent.push(m)});
  const imports=new vm.SyntheticModule(Object.keys(values),function(){for(const[n,v]of Object.entries(values))this.setExport(n,v);},{context});
  await imports.link(()=>{});await imports.evaluate();
  const module=new vm.SourceTextModule(read('worker.js'),{context,importModuleDynamically:()=>imports});
  await module.link(()=>{});await module.evaluate();
  const send=async data=>{await context.onmessage({data});return sent.at(-1);};
  assert.equal((await send({type:'init',pkg:'./pkg/'})).type,'ready');
  const body=()=>send({type:'body',request:2,bytes:new Uint8Array([1]).buffer});
  const run=()=>send({type:'run',request:3,req:{}});
  const fold=extra=>send({type:'fold',request:4,round:3,body:2,...extra});
  await body();const completed=await run();assert.equal((await fold()).type,'folded');
  assert.deepEqual(plain(completed.roundSources),{pattern:'{"pieces":[{"placement":{"part":"torso"}}]}',measurements:'{}',fit:'{}'});
  assert.equal(freed.at(-2),'round','Round sources retained before native handle was freed');
  assert.equal((await fold({round:1})).type,'error');assert.equal(calls.length,1);
  for(const stage of ['run','page','zip','pattern.json','measurements.json','fit_spec.json']) {
    failure=undefined;await run();const count=freed.filter(x=>x==='round').length;
    failure=stage;const refused=await run();assert.equal(refused.type,'error');assert.equal(refused.request,3);
    assert.equal(freed.filter(x=>x==='round').length,count+(stage==='run'?0:1),stage);
    assert.match((await fold()).message,/run a round first/);
  }
  failure=undefined;await run();await send({type:'body',request:5,bytes:new Uint8Array([0]).buffer});
  assert.match((await fold()).message,/load the body model/); // no fallback to the prior model
  await body();assert.equal((await fold()).type,'folded');
  await send({type:'clearBody'});assert.match((await fold()).message,/load the body model/);
  await body();
  const exact='{ "schema": "ftx-body-fit/1", "unrounded": 1.0000000000000002 }';
  assert.match((await fold({bodyFit:exact})).message,/associate/);
  const imported=await fold({bodyFit:exact,bodyFitConsent:true,armDeg:50,selfContactMm:2});
  assert.equal(imported.type,'folded');assert.equal(imported.bodyFitText,exact);
  assert.deepEqual(calls.at(-1),{source:exact,mm:2,twoStart:false,angle:50});
  assert.equal((await fold({bodyFit:exact,bodyFitConsent:true,armDeg:50,selfContactMm:2,twoStart:true})).type,'folded');
  assert.deepEqual(calls.at(-1),{source:exact,mm:2,twoStart:true,angle:50});
  const posed=await fold({bodyFit:exact,bodyFitConsent:true,armDeg:50,selfContactMm:2,twoStart:true,legs:'squat',legFraction:0.25,maxSettleSteps:2});
  assert.equal(posed.type,'folded');assert.equal(posed.bodyFitText,exact);
  assert.deepEqual(calls.at(-1),{source:exact,settings:{self_contact_mm:2,two_start:true,arm_abduction_deg:50,legs:'squat',leg_fraction:0.25,max_settle_steps:2}});
  assert.deepEqual(JSON.parse(posed.settingsText),calls.at(-1).settings);
  assert.equal(posed.reportText,'{"numerical":{"settling":{"steps":2}},"raw":-0.0}');
  const count=calls.length;
  for(const options of [{legs:'kneeling'},{legFraction:Infinity},{maxSettleSteps:-1},{maxSettleSteps:257}]) {
    assert.equal((await fold(options)).type,'error');assert.equal(calls.length,count);
  }
  const tapeCalls=calls.filter(x=>x==='fold').length;
  assert.match((await fold({bodyFit:'refused',bodyFitConsent:true,armDeg:50})).message,/import refused/);
  assert.equal(calls.filter(x=>x==='fold').length,tapeCalls); // never fall back on import failure
  assert.match((await fold({bodyFit:{},bodyFitConsent:true})).message,/JSON text/);
  assert.equal((await fold()).type,'folded');assert.equal(sent.at(-1).bodyFitText,null);
  assert.equal((await fold({armDeg:35})).type,'folded');assert.equal(calls.at(-1),'fold');
  for(const armDeg of [50,0,180]) {
    const result=await fold({armDeg});assert.equal(result.type,'folded',result.message);
    assert.equal(typeof calls.at(-1),'object','An explicit ordinary arm angle needs the configured engine');
    assert.equal(calls.at(-1).settings.arm_abduction_deg,armDeg);assert.equal(calls.at(-1).source,undefined);
    assert.equal(JSON.parse(result.settingsText).arm_abduction_deg,armDeg);
  }
  const beforeInvalid=calls.length;
  for(const armDeg of [null,'','50',NaN,Infinity,-1,181]) {
    assert.match((await fold({armDeg})).message,/angle/);assert.equal(calls.length,beforeInvalid);
  }
  flatOnly=true;await run();assert.equal(sent.at(-1).foldable,false);assert.equal(sent.at(-1).bodyCheckable,true);
  const inspect=extra=>send({type:'inspectBody',request:8,round:3,body:2,...extra});
  const foldCalls=()=>calls.filter(x=>x==='fold'||(typeof x==='object'&&Object.hasOwn(x,'mm'))).length;
  const folds=foldCalls();
  const checked=await inspect();assert.equal(checked.type,'bodyChecked');
  assert.equal(checked.reportText,'{"cloth_simulated":false,"raw":-0.0}');
  assert.deepEqual(calls.at(-1),{inspect:'{}',source:undefined});
  assert.equal((await inspect({round:9})).type,'error');
  assert.match((await inspect({bodyFit:exact})).message,/associate/);
  const accepted=await inspect({bodyFit:exact,bodyFitConsent:true});assert.equal(accepted.bodyFitText,exact);
  assert.deepEqual(calls.at(-1),{inspect:'{}',source:exact});
  assert.match((await inspect({bodyFit:'refused',bodyFitConsent:true})).message,/import refused/);
  assert.equal(foldCalls(),folds); // body checking never calls either cloth path, including failure
  failure='run';assert.equal((await run()).type,'error');assert.match((await inspect()).message,/run a round first/);
  failure=undefined;await run();await send({type:'clearBody'});assert.match((await inspect()).message,/load the body model/);
});

// The original inline workshop script, using a small DOM transport double. These tests inspect
// source/result association and handle lifetime, not browser rendering or computed garment physics.
function draftingPage({traceToken=null,materialToken=null,photoToken=null,bodyToken=null,initialize=true,audit=false}={}) {
  const html=read('index.html'), e=Object.fromEntries([...html.matchAll(/id="([^"]+)"/g)].map(m=>[m[1],new Element()]));
  e.drapeLegs.value='standing';e.drapeLegFraction.value='1';e.maxSettleSteps.value='0';
  e.bodyArmDeg.value='35'; // Match the actual HTML default; explicit blank inputs still refuse.
  for(const el of Object.values(e)) {
    el.addEventListener=(name,fn)=>{const previous=el.handlers[name];el.handlers[name]=(...args)=>{
      const a=previous?.(...args),b=fn(...args);return Promise.all([a,b]);};};
    const classes=new Set(['hidden']);el.classList={add:x=>classes.add(x),remove:x=>classes.delete(x),
      contains:x=>classes.has(x),toggle:(x,on)=>on?classes.add(x):classes.delete(x)};
    el.dataset={};el.querySelectorAll=()=>[];el.scrollIntoView=()=>{};
  }
  e.stature.value='92';e.age.value='30';e.style.value='{}';
  const modes=['chart','tape','file'].map(value=>Object.assign(new Element(),{value,checked:value==='chart'}));
  const messages=[], live=new Map(),windowEvents={},openerMessages=[],popups=[];let worker, next=0;
  const opener={postMessage:(data,origin)=>openerMessages.push({data,origin})};
  class Worker {constructor(){worker=this;}postMessage(m){messages.push(m);}}
  class LocalURL extends URL {}
  LocalURL.createObjectURL=blob=>{const u=`blob:${++next}`;live.set(u,blob);return u;};
  LocalURL.revokeObjectURL=u=>assert.equal(live.delete(u),true);
  const context=vm.createContext({Worker,URL:LocalURL,Blob,JSON,Date,TextDecoder,crypto:{getRandomValues:a=>a.fill(5)},location:{href:'https://unit.invalid/'+(traceToken?'?traceImport='+traceToken:materialToken?'?materialImport='+materialToken:photoToken?'?photoImport='+photoToken:bodyToken?'?bodyFitImport='+bodyToken:'')},
    window:{opener,open:(url,target)=>{const popup={url,target,closed:false,messages:[],postMessage(data,origin){this.messages.push({data,origin});}};popups.push(popup);return popup;},
      addEventListener:(name,fn)=>{const previous=windowEvents[name];windowEvents[name]=(...args)=>{previous?.(...args);return fn(...args);};}},
    localStorage:{getItem:key=>audit&&key==='fab-wb-program'?'"audit"':null,setItem(){}},document:{body:{dataset:{}},getElementById:id=>{assert.ok(e[id],id);return e[id];},
      querySelector:()=>modes.find(m=>m.checked),querySelectorAll:()=>modes,
      createElement:tag=>Object.assign(new Element(),{tag})}});
  vm.runInContext(/<script>([\s\S]*?)<\/script>/.exec(html)[1],context);
  const emit=m=>worker.onmessage({data:m}), last=type=>{
    const m=messages.findLast(m=>m.type===type);
    // Existing semantic assertions decode the transport; fidelity checks inspect messages directly.
    return m?.type==='run'&&typeof m.req==='string'?{...m,req:JSON.parse(m.req)}:m;
  };
  const sheetDictionaries=['DICT_4X4_50','DICT_5X5_50'];
  const engineReady=()=>emit({type:'ready',info:{zouave_bolero:{style:{}}},sheetDictionaries,version:'test',dxf:'test'});
  if(initialize) {engineReady();assert.deepEqual(e.sheetDictionaries.children.map(option=>option.value),sheetDictionaries);}
  const result=(request,extra={})=>emit({type:'result',request:request??last('run').request,foldable:true,bodyCheckable:true,
    res:{title:'current',status:'CONVERGED',basis:{},zip:'round.zip',files:[],validation:{}},blobs:{zip:new Uint8Array([1])},...extra});
  const body=async()=>{e.bodyFile.files=[{arrayBuffer:async()=>new ArrayBuffer(1)}];await e.bodyFile.handlers.change();
    emit({type:'bodyReady',request:last('body').request});};
  const dispatch=(id,event)=>e[id].handlers[event]?.();
  return {e,modes,messages,live,emit,last,result,body,worker,dispatch,engineReady,opener,openerMessages,windowEvents,popups,hasOpener:()=>!!context.window.opener};
}
const alterationTargets = {
  pieces:[{id:'front',vertices:['a','b'],edges:['hem','armhole']},{id:'sleeve',vertices:['ua','top'],edges:['cap','hem']}],
  instances:[{id:'front.R',piece:'front',edges:['hem','armhole']},{id:'front.L',piece:'front',edges:['hem','armhole']},
    {id:'sleeve.R',piece:'sleeve',edges:['cap','hem']}],
  seams:[{id:'cap_front',a:'front.R/armhole',b:'sleeve.R/cap'},{id:'cap_back',a:'front.L/armhole',b:'sleeve.R/hem'}]
};
const alterationPattern=' {"schema":"fabric-pattern/1","meta":{"source_sequence":18446744073709551615,"probe":-0.0},"pieces":[],"seams":[]}\n';
const alterationFit=' {"schema":"fabric-fit/1","probe":1.0,"sequence":18446744073709551615}\n';
async function currentAlterationPage() {
  const p=draftingPage();await p.e.go.handlers.click();
  p.result(undefined,{alterationSources:{pattern:alterationPattern,fit:alterationFit,targets:alterationTargets}});
  for(const id of ['alterAt','alterAdd','alterDx','alterDy'])p.e[id].value='0';
  p.e.alterAxis.value='x';p.e.alterEnd.value='end';p.e.alterRatio.value='1.06';
  return p;
}
test('direct alteration worker retains original sources, rejects stale rounds and keeps refused candidates retryable',async()=>{
  const sent=[],calls=[];let refusal=false,targetFailure=null;
  const values={default:async()=>{},program_info:()=> '{}',calibration_dictionaries:()=> '[]',
    run:()=>({page:()=>'{"status":"CONVERGED","zip":"round.zip"}',zip:()=>new Uint8Array([1]),
      file:n=>new TextEncoder().encode(n==='pattern.json'?alterationPattern:n==='fit_spec.json'?alterationFit:'{}'),free(){}}),
    alteration_targets:source=>{calls.push({targets:source});if(targetFailure)throw targetFailure;return JSON.stringify(alterationTargets);},
    alter_pattern:(source,operation,other)=>{calls.push({source,operation,other});if(refusal)throw Error('unreachable operation');
      return JSON.stringify({pattern_json:alterationPattern.replace('"probe":-0.0','"probe":-0.0,"altered":true'),why:'Changed',targets:alterationTargets});}};
  const context=vm.createContext({JSON,Date,TextDecoder,Uint8Array,WebAssembly,Error,self:{},onmessage:null,postMessage:m=>sent.push(m)});
  const imports=new vm.SyntheticModule(Object.keys(values),function(){for(const[n,v]of Object.entries(values))this.setExport(n,v);},{context});
  await imports.link(()=>{});await imports.evaluate();
  const module=new vm.SourceTextModule(read('worker.js'),{context,importModuleDynamically:()=>imports});
  await module.link(()=>{});await module.evaluate();
  const send=async data=>{await context.onmessage({data});return sent.at(-1);};
  await send({type:'init',pkg:'./pkg/'});
  const result=await send({type:'run',request:4,req:'{}'});
  assert.equal(result.alterationSources.pattern,alterationPattern);assert.equal(result.alterationSources.fit,alterationFit);
  const operation=' {"op":"move","piece":"front","vertex":"a","dx":1.0,"dy":-0.0} ';
  assert.equal((await send({type:'alter',request:5,round:3,operation})).type,'error');
  refusal=true;assert.equal((await send({type:'alter',request:6,round:4,operation})).type,'error');
  refusal=false;const changed=await send({type:'alter',request:7,round:4,operation});
  assert.equal(changed.type,'altered');assert.equal(changed.fit,alterationFit);assert.equal(changed.round,4);
  assert.equal(calls.at(-1).source,alterationPattern);assert.equal(calls.at(-1).operation,operation);
  assert.equal((await send({type:'alter',request:8,round:4,operation})).type,'altered','A cancelled reply can be retried on the same unchanged source');
  const lookup=await send({type:'alterSource',request:9,source:alterationPattern});
  assert.equal(lookup.type,'alterSourceReady');assert.deepEqual(plain(lookup.targets),alterationTargets);
  await send({type:'run',request:10,req:'{}'});
  assert.equal((await send({type:'alter',request:11,round:4,operation})).type,'error');
  targetFailure=Error('direct alteration budget exceeded');
  const ordinary=await send({type:'run',request:12,req:'{}'});
  assert.equal(ordinary.type,'result');assert.equal(ordinary.alterationSources,null);
  assert.match(ordinary.alterationUnavailable,/budget exceeded/);
  targetFailure=new WebAssembly.RuntimeError('unreachable');
  const trapped=await send({type:'run',request:13,req:'{}'});
  assert.equal(trapped.type,'error');assert.equal(trapped.fatal,true);
  assert.equal((await send({type:'run',request:14,req:'{}'})).fatal,true,'A target catalogue trap invalidates the entire module');
});
test('primary direct alterations guide all five native operations and recheck exact accepted pattern and fit text',async()=>{
  for(const [op,inputs,want] of [
    ['slash-spread',{alterAdd:'12',alterAt:'80'},{op:'slash-spread',piece:'front',axis:'x',at:80,add:12}],
    ['move',{alterDx:'3.5',alterDy:'-2'},{op:'move',piece:'front',vertex:'a',dx:3.5,dy:-2}],
    ['true-seam',{alterEnd:'start'},{op:'true-seam',seam:'cap_front',end:'start'}],
    ['cap-ease',{alterPiece:'sleeve'},{op:'cap-ease',piece:'sleeve',seams:['cap_front','cap_back'],target:1.06}],
    ['transfer-curve',{}, {op:'transfer-curve',from:'front.R/hem',to:'front/hem'}],
  ]) {
    const p=await currentAlterationPage();assert.equal(p.e.alterSection.classList.contains('hidden'),false);
    assert.deepEqual(p.e.alterPiece.children.map(o=>o.value),['front','sleeve']);
    p.e.alterOperation.value=op;p.dispatch('alterOperation','change');
    for(const [id,value]of Object.entries(inputs))p.e[id].value=value;
    p.e.alterCapSeams.selectedOptions=[{value:'cap_front'},{value:'cap_back'}];
    p.dispatch('alterPiece','change');p.e.alterApply.handlers.click();
    const msg=p.last('alter');assert.deepEqual(JSON.parse(msg.operation),want);
    assert.equal(p.live.size,0,'Pending alteration withdraws prior round artifacts');assert.equal(p.e.foldGo.disabled,true);
    assert.equal(msg.source,op==='transfer-curve'?alterationPattern:undefined);
    const changed=alterationPattern.replace('"pieces":[]','"pieces":[],"changed":true');
    p.emit({type:'altered',request:msg.request,round:msg.round,pattern:changed,fit:alterationFit,why:'Native history sentence'});
    await new Promise(resolve=>setImmediate(resolve));
    const next=p.messages.findLast(m=>m.type==='run');
    assert.ok(next.req.includes('"pattern":'+changed));assert.ok(next.req.includes('"fit_spec":'+alterationFit));
    assert.equal(JSON.parse(next.req).body.stature_cm,92);assert.equal(p.e.alterImportNote.hidden,false);
    assert.match(p.e.alterImportText.textContent,/Native history sentence/);
    assert.equal(await p.live.get(p.e.alterDownload.href).text(),changed);
    assert.equal(p.e.undoAlter.disabled,false);
    p.e.undoAlter.handlers.click();await new Promise(resolve=>setImmediate(resolve));
    assert.ok(p.messages.findLast(m=>m.type==='run').req.includes('"pattern":'+alterationPattern));
    assert.equal(p.e.undoAlter.disabled,true);
  }
});
